import {
  BarChart,
  Callout,
  Divider,
  Grid,
  H1,
  H2,
  H3,
  LineChart,
  Pill,
  Row,
  Stack,
  Stat,
  Table,
  Text,
  useState,
} from "cursor/canvas";

type Policy = "accepted" | "waterfall";
type AsOf = "2026-11-10" | "2026-11-12";

type WorkState = "done" | "open" | "cancelled";

type Work = {
  id: string;
  contract: string;
  title: string;
  price: number;
  state: WorkState;
  fifo: number;
};

function money(n: number): string {
  const sign = n < 0 ? "−" : "";
  const body = String(Math.abs(Math.round(n))).replace(
    /\B(?=(\d{3})+(?!\d))/g,
    " ",
  );
  return `${sign}${body}`;
}

function worksOn(asOf: AsOf): Work[] {
  const packaging: WorkState = asOf === "2026-11-12" ? "done" : "open";
  return [
    { id: "W-11", contract: "D-1", title: "Съёмка: весенняя коллекция", price: 100000, state: "done", fifo: 1 },
    { id: "W-12", contract: "D-1", title: "Съёмка: лето", price: 100000, state: "done", fifo: 2 },
    { id: "W-13", contract: "D-1", title: "Съёмка: аксессуары", price: 100000, state: "cancelled", fifo: 9 },
    { id: "W-14", contract: "D-1", title: "Съёмка: осень", price: 100000, state: "done", fifo: 3 },
    { id: "W-15", contract: "D-1", title: "Съёмка: зима", price: 100000, state: "open", fifo: 4 },
    { id: "W-16", contract: "D-1", title: "Съёмка: новогодняя", price: 100000, state: "open", fifo: 5 },
    { id: "W-21", contract: "D-2", title: "Логотип", price: 20000, state: "done", fifo: 1 },
    { id: "W-22", contract: "D-2", title: "Фирменный стиль", price: 30000, state: "done", fifo: 2 },
    { id: "W-23", contract: "D-2", title: "Упаковка", price: 40000, state: packaging, fifo: 3 },
  ];
}

function poolOf(contract: string, asOf: AsOf): number {
  if (contract === "D-1") return 300000;
  return asOf === "2026-11-12" ? 95000 : 75000;
}

function cashOf(contract: string, asOf: AsOf): number {
  if (contract === "D-1") return 315000;
  return poolOf(contract, asOf);
}

function allocate(asOf: AsOf, policy: Policy) {
  const works = worksOn(asOf);
  const paid: Record<string, number> = {};
  for (const work of works) paid[work.id] = 0;

  const cap = (work: Work): number => {
    if (work.state === "cancelled") return 0;
    if (work.state === "done") return work.price;
    return policy === "waterfall" ? work.price : 0;
  };

  paid["W-14"] = 15000;

  for (const contract of ["D-1", "D-2"]) {
    let pool = poolOf(contract, asOf);
    const ordered = works
      .filter((work) => work.contract === contract)
      .sort((a, b) => a.fifo - b.fifo);
    for (const work of ordered) {
      const room = cap(work) - paid[work.id];
      const take = Math.min(Math.max(room, 0), pool);
      paid[work.id] += take;
      pool -= take;
    }
  }

  return { works, paid };
}

function stateLabel(state: WorkState, id: string, asOf: AsOf): string {
  if (state === "cancelled") return "отменена";
  if (state === "done") return "принята";
  if (id === "W-23" && asOf === "2026-11-10") return "ещё не принята";
  return "в плане";
}

export default function AdvanceReportReview() {
  const [asOf, setAsOf] = useState<AsOf>("2026-11-10");
  const [policy, setPolicy] = useState<Policy>("accepted");
  const { works, paid } = allocate(asOf, policy);

  const unalloc = (contract: string) => {
    const allocated = works
      .filter((work) => work.contract === contract)
      .reduce((sum, work) => sum + paid[work.id], 0);
    return cashOf(contract, asOf) - allocated;
  };

  const active = (contract: string) =>
    works
      .filter((work) => work.contract === contract && work.state !== "cancelled")
      .reduce((sum, work) => sum + work.price, 0);

  const d1Left = active("D-1") - cashOf("D-1", asOf);
  const d2Left = active("D-2") - cashOf("D-2", asOf);
  const d1Free = unalloc("D-1");
  const d2Free = unalloc("D-2");

  const workRows = works.map((work) => {
    const got = paid[work.id];
    const left = work.state === "cancelled" ? 0 : work.price - got;
    return [
      work.id,
      work.contract,
      work.title,
      stateLabel(work.state, work.id, asOf),
      money(work.price),
      money(got),
      money(left),
    ];
  });

  const workTones = works.map((work) => {
    if (work.state === "cancelled") return "warning" as const;
    if (work.id === "W-23") return "info" as const;
    if (work.state === "open" && paid[work.id] > 0) return "info" as const;
    if (work.state === "done" && paid[work.id] === work.price) return "success" as const;
    return "neutral" as const;
  });

  return (
    <Stack gap={24}>
      <Stack gap={8}>
        <H1>Аванс по договору: разбор тестового</H1>
        <Text tone="secondary">
          Условие и три CSV, решения кандидата в папке нет. Контрольная дата
          10.11.2026 стоит между приёмкой упаковки (11.11) и платежом P-8
          (12.11). Суммы ниже — опорный отчёт: свободный аванс зачитывается на
          принятые работы по дате приёмки, платёж с work_id садится на свою
          работу первым. Переключатели меняют дату и правило хвоста.
        </Text>
        <Text size="small" tone="tertiary">
          Источник: data/contracts.csv, works.csv, payments.csv. Деньги в
          рублях, в файлах все суммы без копеек.
        </Text>
      </Stack>

      <Row gap={8} wrap>
        <Pill active={asOf === "2026-11-10"} onClick={() => setAsOf("2026-11-10")}>
          На 10.11.2026
        </Pill>
        <Pill active={asOf === "2026-11-12"} onClick={() => setAsOf("2026-11-12")}>
          На 12.11.2026
        </Pill>
        <Pill active={policy === "accepted"} onClick={() => setPolicy("accepted")}>
          Аванс только на принятые
        </Pill>
        <Pill active={policy === "waterfall"} onClick={() => setPolicy("waterfall")}>
          Хвост на следующие работы
        </Pill>
      </Row>

      <Grid columns={4} gap={16}>
        <Stat value={money(d1Left)} label="Остаток D-1, руб." />
        <Stat
          value={money(d2Left)}
          label="Остаток D-2, руб."
          tone={d2Left < 0 ? "danger" : "info"}
        />
        <Stat value={money(d1Free)} label="Свободный аванс D-1, руб." />
        <Stat
          value={money(d2Free)}
          label="Свободный аванс D-2, руб."
          tone={d2Free > 0 && asOf === "2026-11-12" ? "warning" : undefined}
        />
      </Grid>

      <Text size="small" tone="secondary">
        Остаток — живой объём работ минус деньги, которые уже ушли. Отмена W-13
        снимает 100 000 с объёма D-1. Очередь P-4 (150 000) в эти цифры не
        входит. Смена правила двигает свободный аванс между строкой договора и
        конкретными работами, касса та же.
      </Text>

      <Stack gap={8}>
        <H2>Работы на выбранную дату</H2>
        <Table
          headers={["Работа", "Договор", "Название", "Состояние", "Цена", "Выплачено", "Осталось"]}
          rows={workRows}
          columnAlign={["left", "left", "left", "left", "right", "right", "right"]}
          rowTone={workTones}
          striped
        />
        <Text size="small" tone="tertiary">
          «Выплачено» — зачёт аванса и привязанных платежей, не касса договора.
          У W-14 в зачёте 15 000 материалов (P-3) и 85 000 из аванса P-1.
        </Text>
      </Stack>

      <Stack gap={8}>
        <H2>Итог по договорам</H2>
        <Table
          headers={[
            "Договор",
            "Сумма договора",
            "Живой объём",
            "Ушло денег",
            "Свободный аванс",
            "Остаток",
            "В очереди",
          ]}
          rows={[
            ["D-1 Студия «Свет»", "600 000", money(active("D-1")), money(cashOf("D-1", asOf)), money(d1Free), money(d1Left), "150 000"],
            ["D-2 Иван Петров", "90 000", money(active("D-2")), money(cashOf("D-2", asOf)), money(d2Free), money(d2Left), "0"],
          ]}
          columnAlign={["left", "right", "right", "right", "right", "right", "right"]}
          rowTone={["neutral", d2Left < 0 ? "danger" : "info"]}
          striped
        />
        <Text size="small" tone="tertiary">
          Живой объём — сумма цен работ без отменённых. На 10.11 по D-2 ушло
          75 000 (P-5, P-6, P-7). P-8 на 20 000 датирован 12.11.
        </Text>
      </Stack>

      <Grid columns={2} gap={20}>
        <Stack gap={8}>
          <H3>D-2: касса и принятые акты, тыс. руб.</H3>
          <LineChart
            categories={["25.09", "01.10", "10.10", "30.10", "02.11", "10.11", "11.11", "12.11"]}
            series={[
              { name: "Ушло денег", data: [45, 45, 45, 70, 75, 75, 75, 95], tone: "info" },
              { name: "Принято актами", data: [0, 20, 50, 50, 50, 50, 90, 90], tone: "success" },
            ]}
            referenceLines={[{ value: 90, label: "Договор 90", tone: "warning" }]}
            height={220}
            valueSuffix=" тыс."
          />
          <Text size="small" tone="tertiary">
            Ось X — дата события, ось Y — тысячи рублей, накопительно с 25.09.
            Вертикаль отчёта — 10.11: касса 75, принято 50. Переплата видна с
            12.11, когда касса 95 пересекает сумму договора.
          </Text>
        </Stack>
        <Stack gap={8}>
          <H3>D-1: из чего складываются 315 000</H3>
          <BarChart
            categories={["Аванс P-1", "Материалы P-3", "Возврат P-2", "Очередь P-4"]}
            series={[{ name: "Сумма в отчёте на 10.11, тыс. руб.", data: [300, 15, 0, 0], tone: "info" }]}
            height={220}
            valueSuffix=" тыс."
            showValues
          />
          <Text size="small" tone="tertiary">
            Ось X — платёж, ось Y — тысячи рублей, которые входят в «ушло
            денег» на 10.11. P-2 к этой дате уже возвращён, P-4 ещё не оплачен,
            поэтому оба столбца нулевые. Номинал P-2 — 50 тыс., P-4 — 150 тыс.
          </Text>
        </Stack>
      </Grid>

      <Divider />

      <Stack gap={8}>
        <H2>Где решение расходится с выгрузкой</H2>
        <Table
          headers={["Факт в данных", "Как читать на 10.11", "Что поедет, если прочитать иначе"]}
          rows={[
            [
              "W-23 status=done, completed_at=11.11",
              "На 10.11 работа ещё не принята",
              "В «принято» попадёт 40 000, и 25 000 аванса сядут на упаковку",
            ],
            [
              "P-8 paid 12.11, 20 000",
              "В кассу на 10.11 не входит",
              "По D-2 будет 95 000 при договоре 90 000 уже на контрольной дате",
            ],
            [
              "P-2 refunded 10.09, 50 000",
              "На 10.11 вклад нулевой",
              "Аванс D-1 раздуется на 50 000. Между 02.09 и 10.09 эти деньги ещё были у подрядчика",
            ],
            [
              "P-4 queued 01.11, 150 000",
              "Отдельная строка, не «выплачено»",
              "Касса D-1 станет 465 000, остаток съёжится на 150 000",
            ],
            [
              "W-13 cancelled 12.10, 100 000",
              "В живой объём не входит, зачёт аванса её пропускает",
              "Аванс 300 000 закроет отменённую съёмку, и осень останется должной",
            ],
            [
              "P-1 и платежи D-2 без work_id",
              "Общий котёл договора, потом зачёт по дате приёмки",
              "Пропорция по всем работам размажет аванс на план и на отмену",
            ],
            [
              "purpose: «Остаток» 25 000, «Доплата» 5 000",
              "Подпись не равна сумме. Считать status и даты",
              "Парсер назначения соберёт остаток, которого в цифрах нет",
            ],
            [
              "Подрядчик D-2 и purpose P-2 с запятой в кавычках",
              "Нормальный CSV",
              "split по запятой сдвинет колонки второй строки",
            ],
          ]}
          rowTone={["info", "info", "warning", "warning", "warning", "neutral", "neutral", "neutral"]}
          striped
        />
      </Stack>

      <Callout tone="warning" title="Что бухгалтер должна подтвердить">
        Свободный аванс висит на договоре или его уже кладут на работы, которые
        ещё не приняты. Отменённая съёмка аксессуаров вычитается из договора.
        15 000 «материалов» по осенней съёмке — часть цены 100 000 или расход
        сверх неё. Очередь 150 000 в «выплачено» не ставится. Доплата 5 000 по
        D-2 на 12.11 даёт выплаты 95 000 при договоре 90 000 — это согласованная
        переплата или ошибка.
      </Callout>

      <Stack gap={8}>
        <H2>Что контрольная дата не ловит</H2>
        <Text>
          На сам 10.11 нет ни платежа, ни приёмки, ни отмены. Сравнение «строго
          меньше даты» и «меньше либо равно» на проверочном прогоне совпадёт.
          Все суммы целые и далеко от границы float, так что требование считать
          в копейках эти файлы не наказывают. Частичного возврата нет: P-2
          возвращается целиком. Сумма работ в файле равна сумме договора, зазор
          100 000 появляется только после отмены W-13.
        </Text>
        <Text>
          Сильное решение принимает дату аргументом, восстанавливает состояние
          из paid_at, refunded_at, completed_at и cancelled_at и пишет в
          DECISIONS.md, куда девается хвост аванса. Слабое решение складывает
          amount и верит колонке status: W-23 уже сдана, P-8 уже выплачен,
          очередь попадает в выплаченное.
        </Text>
      </Stack>

      <Stack gap={8}>
        <H2>Как отличить сдачу</H2>
        <Table
          headers={["Уровень", "Что видно в сдаче"]}
          rows={[
            [
              "Закрывает задачу",
              "Дата-параметр, P-8 и W-23 выпали на 10.11, P-2 даёт ноль, P-4 не в выплаченном, строки работ и итог договора, Decimal, команда запуска",
            ],
            [
              "Понимает учёт",
              "Привязанный платёж раньше котла, зачёт по дате приёмки, отмена не съедает аванс, свободный аванс отдельной строкой, переплата 5 000 проявляется на 12.11",
            ],
            [
              "Честно про дырку",
              "DECISIONS.md на развилку хвоста, на материалы сверх цены и на очередь. Записка просит бухгалтера подтвердить именно это",
            ],
          ]}
          rowTone={["success", "info", "warning"]}
          striped
        />
      </Stack>
    </Stack>
  );
}

"""Отчёт по авансам договоров на выбранную дату.

Сейчас скрипт только проверяет аргументы и доступ к файлам.
Расчёт сумм подключается на следующих этапах.
"""

from __future__ import annotations

import argparse
import logging
import os
import sys
from datetime import date, datetime
from pathlib import Path


logger = logging.getLogger("advance_report")

REQUIRED_FILES = ("contracts.csv", "works.csv", "payments.csv")
MAX_PATH_LENGTH = 4096
LOG_TEXT_LIMIT = 300


class PreflightError(Exception):
    """Входные данные или права не дают даже начать расчёт."""


def for_log(value: object, limit: int = LOG_TEXT_LIMIT) -> str:
    text = str(value).replace("\\", "\\\\").replace("\r", "\\r").replace("\n", "\\n")
    if len(text) > limit:
        return text[:limit] + "...(обрезано)"
    return text


def configure_logging() -> None:
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s %(levelname)s %(message)s",
        stream=sys.stderr,
    )


def parse_report_date(value: str) -> date:
    text = value.strip()
    if not text:
        raise argparse.ArgumentTypeError(
            "Дата пустая. Ожидается ГГГГ-ММ-ДД или ДД.ММ.ГГГГ."
        )
    if len(text) > 32:
        raise argparse.ArgumentTypeError("Дата длиннее 32 символов.")
    for fmt in ("%Y-%m-%d", "%d.%m.%Y"):
        try:
            return datetime.strptime(text, fmt).date()
        except ValueError:
            continue
    raise argparse.ArgumentTypeError(
        "Некорректная дата: {0!r}. Ожидается ГГГГ-ММ-ДД или ДД.ММ.ГГГГ.".format(text)
    )


def parse_path_arg(value: str) -> Path:
    text = value.strip()
    if not text:
        raise argparse.ArgumentTypeError("Путь пустой.")
    if "\x00" in text:
        raise argparse.ArgumentTypeError("В пути есть символ NUL.")
    if len(text) > MAX_PATH_LENGTH:
        raise argparse.ArgumentTypeError(
            "Путь длиннее {0} символов.".format(MAX_PATH_LENGTH)
        )
    return Path(text)


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description=(
            "Отчёт на дату: по каждой работе цена, выплачено и остаток, "
            "итоги по каждому договору."
        ),
    )
    parser.add_argument(
        "--as-of",
        type=parse_report_date,
        default=date(2026, 11, 10),
        help="Дата отчёта: ГГГГ-ММ-ДД или ДД.ММ.ГГГГ (по умолчанию 2026-11-10).",
    )
    parser.add_argument(
        "--data",
        type=parse_path_arg,
        default=Path("data"),
        help="Папка с contracts.csv, works.csv и payments.csv (по умолчанию data).",
    )
    parser.add_argument(
        "--out",
        type=parse_path_arg,
        default=Path("out"),
        help="Папка для CSV отчёта (по умолчанию out).",
    )
    return parser.parse_args(argv)


def resolve_existing_dir(path: Path, label: str) -> Path:
    try:
        resolved = path.expanduser().resolve()
    except OSError as exc:
        raise PreflightError(
            "{0}: путь не разбирается ({1}): {2}".format(label, for_log(path), exc.strerror or exc)
        ) from exc
    logger.info("%s: проверяю %s", label, for_log(resolved))
    if not resolved.exists():
        raise PreflightError("{0} не найдена: {1}".format(label, resolved))
    if not resolved.is_dir():
        raise PreflightError("{0} оказалась файлом, нужна папка: {1}".format(label, resolved))
    if not os.access(resolved, os.R_OK | os.X_OK):
        raise PreflightError("Нет прав на чтение папки {0}: {1}".format(label, resolved))
    return resolved


def check_source_file(directory: Path, name: str) -> None:
    path = directory / name
    logger.info("Файл %s: проверяю %s", name, for_log(path))
    if not path.exists():
        raise PreflightError("Нет файла {0}".format(path))
    if path.is_symlink():
        logger.info("Файл %s: это ссылка на %s", name, for_log(path.resolve()))
    if not path.is_file():
        raise PreflightError("{0} не является файлом".format(path))
    try:
        size = path.stat().st_size
    except OSError as exc:
        raise PreflightError(
            "Не удалось прочитать сведения о {0}: {1}".format(path, exc.strerror or exc)
        ) from exc
    if size == 0:
        raise PreflightError("Файл пустой: {0}".format(path))
    try:
        with path.open("rb") as handle:
            handle.read(1)
    except PermissionError as exc:
        raise PreflightError("Нет прав на чтение {0}".format(path)) from exc
    except OSError as exc:
        raise PreflightError(
            "Файл нельзя прочитать {0}: {1}".format(path, exc.strerror or exc)
        ) from exc
    logger.info("Файл %s: доступен, размер %s байт", name, size)


def check_output_dir(path: Path, data_dir: Path) -> Path:
    try:
        resolved = path.expanduser().resolve()
    except OSError as exc:
        raise PreflightError(
            "Папка отчёта не разбирается ({0}): {1}".format(for_log(path), exc.strerror or exc)
        ) from exc
    logger.info("Папка отчёта: проверяю %s", for_log(resolved))
    if resolved == data_dir:
        raise PreflightError(
            "Папка отчёта совпадает с папкой данных ({0}). "
            "Исходные CSV нельзя писать поверх выгрузки.".format(resolved)
        )
    if resolved.exists():
        if not resolved.is_dir():
            raise PreflightError("Папка отчёта оказалась файлом: {0}".format(resolved))
        probe_dir = resolved
    else:
        probe_dir = resolved.parent
        if not probe_dir.is_dir():
            raise PreflightError(
